    "keyFactsHtml": "<table>\n<thead>\n<tr>\n<th>Что проверять</th>\n<th>Зачем</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Марка стали</td>\n<td>соответствие заказу и чертежу</td>\n</tr>\n<tr>\n<td>Номер плавки и партии</td>\n<td>прослеживаемость материала</td>\n</tr>\n<tr>\n<td>Обозначение стандарта</td>\n<td>ГОСТ на продукцию, например 4986-79</td>\n</tr>\n<tr>\n<td>Размеры и масса</td>\n<td>сверка с фактической поставкой</td>\n</tr>\n<tr>\n<td>Химический состав</td>\n<td>подтверждение марки</td>\n</tr>\n<tr>\n<td>Механические свойства</td>\n<td>расчётные значения для детали</td>\n</tr>\n<tr>\n<td>Состояние поставки</td>\n<td>М, ПН, Н, ВН или термообработка</td>\n</tr>\n<tr>\n<td>Отметка контроля</td>\n<td>подтверждение приёмки изготовителем</td>\n</tr>\n</tbody>\n</table>",
